SourceCode.Declaration:
/// <summary>
/// CB629_TMSEngineTOShipped.
/// Class responsible for populating the TMS engine TO temp table (calculation table).
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::TransferOrderShipped)]
class METTMSEngineTOLinesTmpBuilder_Shipped extends METTMSEngineLinesTmpBuilder
{
    METSalesOrderShipmentLoadLines salesOrderShipmentLoadLinesQueryRun;
    METWMSPicklistNumber wmsPicklistNumber;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_transferTable">InventTransferTable record</param>
/// <param name = "_shipmentId">SO finalisation shipment id</param>
/// <param name = "_wmsPicklistNumber">AIS WMS picking list number</param>
void new(InventTransferTable _transferTable, METShipmentId _shipmentId, METWMSPicklistNumber _wmsPicklistNumber)
{
    shipmentId = _shipmentId;
    wmsPicklistNumber = _wmsPicklistNumber;

    this.init(_transferTable);
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_transferLine">Transfer order line</param>
/// <returns>Transfer order quantity</returns>
protected Qty lineShipQty(METTMSSourceRecordLineMap _sourceLine)
{
    return salesOrderShipmentLoadLinesQueryRun.PickedQty;
}

/// <summary>
/// CCR only applies to CB629
/// </summary>
/// <param name = "_transferLine">TransferLine line</param>
/// <returns>Yes if supplier warehouse is CCR or pick director; otherwise, false.</returns>
protected NoYes setSuppWhsHasCCR(METTMSSourceRecordLineMap _sourceLine)
{
    NoYes ret = NoYes::No;

    // For CB629 set CCR if the supplying WH has CCR or pick director
    if (inventLocation.METCCR || inventLocation.METPickDirector)
    {
        if (METCCRTable::existItemInventLocationWMSPickList(_sourceLine.ItemId,
                                                            inventLocation.InventLocationId,
                                                            wmsPicklistNumber))
        {
            ret = NoYes::Yes;

            // set hasCCR if at least one line in temp table has SuppWhsHasCCR = Yes
            if (!hasCCR)
            {
                hasCCR = true;
            }
        }
    }

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected Query initQuery()
{
    Query ret;

    ret = super();

    QueryBuildDataSource qbds = ret.dataSourceTable(this.getLineTableId());
    qbds.addRange(fieldNum(InventTransferLine, TransferId)).value(queryValue(sourceRecord.OrderId));

    // extend the query to add a link to salesOrderShipmentLoadLines so that we can get the new PickedQty instead of InventTransferLine.QtyTransfer
    QueryBuildDataSource qbdsShipmentLines = qbds.addDataSource(tableNum(METSalesOrderShipmentLoadLines));
    qbdsShipmentLines.joinMode(JoinMode::InnerJoin);
    qbdsShipmentLines.addLink(fieldNum(InventTransferLine, InventTransId), fieldNum(METSalesOrderShipmentLoadLines, InventTransId));

    // filter shipment lines for the shipment being confirmed
    qbdsShipmentLines.addRange(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId)).value(queryValue(shipmentId));

    return ret;
}

/// <summary>
/// Get tables from _queryRun object used to fill the temp table
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object used to fill the temp table</param>
/// <returns>Container of records from the <c>QueryRun</c> object</returns>
protected METTMSSourceRecordLineMap getTablesQueryRun(QueryRun _queryRun)
{
    InventTransferLine ret = super(_queryRun);

    // get the METSalesOrderShipmentLoadLines record from the queryRun object, specific to PackingSlip
    salesOrderShipmentLoadLinesQueryRun = _queryRun.get(tableNum(METSalesOrderShipmentLoadLines));

    return ret;
}
